    69	/** Fail-closed reason: the worktree carries uncommitted MATERIAL (source) state, so the HEAD materialHash cannot honestly bind a review result. */
    70	export const CROSS_HOST_REVIEW_DIRTY_WORKTREE = 'cross_host_review_dirty_worktree' as const;
    71	/** Fail-closed reason: the committed HEAD moved after the review binding was computed, so the verdict would bind to a stale commit. */
    72	export const CROSS_HOST_REVIEW_HEAD_DRIFT = 'cross_host_review_head_drift' as const;
    73	
    74	/**
    75	 * Integrity preflight (host-B escalation-lane fix): FAIL CLOSED before any codex
    76	 * spawn when the worktree has uncommitted MATERIAL (source) drift versus HEAD.
    77	 *
    78	 * WHY: the recorded verdict is bound to `currentMaterialHash(root,'HEAD',...)`,
    79	 * which hashes the COMMITTED tree (`git ls-tree HEAD`). Codex reviews a detached
    80	 * snapshot of that committed tree, so the live worktree must not contain material
    81	 * source edits that are outside the captured commit. Throwing here guarantees the
    82	 * operator's source state is exactly the captured HEAD tree (modulo `.lattice/`
    83	 * metadata Codex never reads), so the bound materialHash is HONEST. This matches
    84	 * the repo's "commit before review" discipline.
    85	 *
    86	 * `.lattice/` EXCLUSION: the story's own Lattice metadata dir churns constantly
    87	 * DURING a story (activity log, locks, the story's own test-evidence/checklist),
    88	 * and Codex reviews SOURCE, not story bookkeeping — so any path under `.lattice/`
    89	 * is dropped from the material set. Everything else that git reports (tracked
    90	 * modifications + untracked files via `--untracked-files=all`) counts as material
    91	 * drift.
    92	 *
    93	 * NOTE ON `currentMaterialHash`: it has no clean working-tree hash mode — it only
    94	 * hashes a git ref via `git ls-tree -r <ref>` (the committed tree), so it cannot
    95	 * be repointed at the live worktree. The fail-closed dirty preflight is therefore
    96	 * the correct fix: keep the honest committed-tree hash and refuse to bind it to a
    97	 * review of a dirty tree.
    98	 */
    99	// Exported for the porcelain first-row regression smoke (B-d6a0); not a CLI command.
   100	export function assertMaterialCleanForReview(gitCwd: string): void {
   101	  let raw: string;
   102	  try {
   103	    // No full-output trim(): it would strip the first porcelain row's leading
   104	    // status space (" M path" -> "M path"), shifting the fixed-width path
   105	    // offset so the first row's `.lattice/...` path reads as "lattice/..." and
   106	    // false-blocks the preflight on metadata-only dirt.
   107	    raw = execFileSync('git', ['status', '--porcelain', '--untracked-files=all'], {
   108	      cwd: gitCwd,
   109	      encoding: 'utf-8',
   110	      stdio: ['pipe', 'pipe', 'pipe'],
   111	      maxBuffer: GIT_TREE_OUTPUT_MAX_BUFFER,
   112	    });
   113	  } catch (err) {
   114	    // Fail closed: if we cannot even determine the worktree state, we cannot
   115	    // assert HEAD honestly binds the reviewed tree.
   116	    throw new Error(
   117	      `cross_host_review: ${CROSS_HOST_REVIEW_DIRTY_WORKTREE} — cannot inspect worktree state to confirm it matches HEAD `
   118	      + `(${err instanceof Error ? err.message : String(err)}); refusing to spawn the codex review subprocess.`,
   119	    );
   120	  }
   121	  const rows = raw.split('\n').map(line => line.trimEnd()).filter(Boolean);
   122	  if (rows.length === 0) return;
   123	  const latticePrefix = `${LATTICE_DIR}/`; // e.g. ".lattice/"
   124	  const material: string[] = [];
   125	  for (const line of rows) {
   126	    if (line.length < 4) continue;
   127	    // Porcelain v1: "XY <path>" or "XY <old> -> <new>" for renames.
   128	    const pathText = line.slice(3).trim();
   129	    const paths = pathText.includes(' -> ')
   130	      ? pathText.split(' -> ').map(p => p.trim().replace(/^"|"$/g, ''))
   131	      : [pathText.replace(/^"|"$/g, '')];
   132	    for (const path of paths) {
   133	      const normalized = path.replace(/\\/g, '/');
   134	      if (!normalized) continue;
   135	      // Drop the story's own Lattice metadata dir — Codex reviews source, not
   136	      // story bookkeeping, and `.lattice/` churns constantly during a story.
   137	      if (normalized === LATTICE_DIR || normalized.startsWith(latticePrefix)) continue;
   138	      material.push(normalized);
   139	    }
   140	  }
   141	  if (material.length > 0) {
   142	    const sample = [...new Set(material)].sort().slice(0, 5).join(', ');
   143	    throw new Error(
   144	      `cross_host_review: ${CROSS_HOST_REVIEW_DIRTY_WORKTREE} — the worktree has uncommitted MATERIAL (source) changes `
   145	      + `versus HEAD (${sample}${material.length > 5 ? ', …' : ''}). Codex reviews a detached snapshot of HEAD, and the `
   146	      + `recorded verdict binds to that HEAD materialHash (the committed tree), so uncommitted source state would make the `
   147	      + `operator-facing review result misleading. Commit or stash the source changes before cross_host_review (commit-before-review), or `
   148	      + `exclude only .lattice/ metadata. Refusing to spawn the codex review subprocess (fail-closed).`,
   149	    );
   150	  }
   151	}
