   440	/**
   441	 * STRICT Finding schema (sweep hardening). `.strict()` REJECTS unknown keys — the
   442	 * host-A findings file is untrusted caller-supplied input, so an extra/contradictory
   443	 * key (or a missing required field, or a wrong-typed field) must FAIL CLOSED, not be
   444	 * silently dropped. Mirrors the frozen `Finding` shape (adversarial-review.ts).
   445	 */
   446	const hostAFindingSchema = z.object({
   447	  severity: z.enum(FINDING_SEVERITIES),
   448	  title: z.string(),
   449	  file: z.string(),
   450	  line: z.number(),
   451	  issue: z.string(),
   452	  fix: z.string(),
